package ru.murad.yourmarket.service;
import org.junit.jupiter.api.Test;import ru.murad.yourmarket.model.Advertisement;import ru.murad.yourmarket.service.impl.AdvertisementExpirationServiceImpl;import ru.murad.yourmarket.telegram.TelegramGateway;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AdvertisementExpirationServiceTest {AdvertisementLifecycleTransactionService lifecycle=mock(AdvertisementLifecycleTransactionService.class);ChannelMessageDeletionService deletion=mock(ChannelMessageDeletionService.class);TelegramGateway telegram=mock(TelegramGateway.class);AdvertisementExpirationServiceImpl service=new AdvertisementExpirationServiceImpl(lifecycle,deletion,telegram);UUID id=UUID.randomUUID(),op=UUID.randomUUID();Advertisement ad=Advertisement.builder().id(id).chatId(1L).build();
@Test void onlyClaimOwnerFinishingSendsNotification(){when(lifecycle.claimExpiration(id)).thenReturn(new AdvertisementLifecycleTransactionService.ExpirationClaim(ad,op));when(deletion.deleteAll(id)).thenReturn(true);when(lifecycle.finishExpiration(id,op)).thenReturn(ad);assertTrue(service.expire(id));verify(telegram).sendText(1L,"Срок публикации объявления истёк");}
@Test void partialDeletionReleasesClaimWithoutNotification(){when(lifecycle.claimExpiration(id)).thenReturn(new AdvertisementLifecycleTransactionService.ExpirationClaim(ad,op));when(deletion.deleteAll(id)).thenReturn(false);assertFalse(service.expire(id));verify(lifecycle).releaseExpiration(id,op);verifyNoInteractions(telegram);}
@Test void lostOwnershipDoesNotNotify(){when(lifecycle.claimExpiration(id)).thenReturn(new AdvertisementLifecycleTransactionService.ExpirationClaim(ad,op));when(deletion.deleteAll(id)).thenReturn(true);when(lifecycle.finishExpiration(id,op)).thenReturn(null);assertFalse(service.expire(id));verifyNoInteractions(telegram);}
@Test void secondWorkerWithoutClaimDoesNothing(){when(lifecycle.claimExpiration(id)).thenReturn(null);assertFalse(service.expire(id));verifyNoInteractions(deletion,telegram);}}
